// OSM road classes for the live GSI builder, from VersaTiles' public OSM vector tiles (Shortbread schema, CORS-enabled).
// GSI rdCtg=1 (prefectural) cannot tell 主要地方道 (main) from 一般県道 (ordinary); OSM primary/secondary does
// (99.5% length-weighted on census sections, research-traffic.md). street_labels carry national route refs (trunk).
import Pbf from '../../vendor/pbf.mjs';
import { VectorTile } from '../../vendor/vector-tile.mjs';
import { bikeWayType } from '../bike-infra.mjs';

// segments in local metres: { a:[x,y], b:[x,y], kind, ref }. If bikeLines is given, bike facilities in the streets
// layer (kind=cycleway, or path/footway/... with bicycle=yes) are appended to it as polylines in local metres.
export function decodeOsmStreets(tiles, buffers, toLocal, bikeLines = null) {
  const segs = [];
  tiles.forEach((t, k) => {
    const buf = buffers[k]; if (!buf || !buf.length) return;
    const vt = new VectorTile(new Pbf(buf));
    for (const [layer, isLabel] of [['streets', false], ['street_labels', true]]) {
      const L = vt.layers[layer]; if (!L) continue;
      const E = L.extent, n = 2 ** t.z;
      for (let i = 0; i < L.length; i++) {
        const f = L.feature(i); if (f.type !== 2) continue;
        const p = f.properties, kind = String(p.kind ?? '');
        const bt = bikeLines && !isLabel ? bikeWayType(p) : 0;
        if (bt) {
          // bikeLines = { sep, shared }: dedicated cycleways vs shared sidewalks/paths (自転車歩行者道)
          const target = bt === 2 ? bikeLines.sep : bikeLines.shared;
          for (const line of f.loadGeometry()) target.push(line.map(({ x, y }) => toLocal([((t.x + x / E) / n) * 360 - 180,
            (180 / Math.PI) * Math.atan(Math.sinh(Math.PI - (2 * Math.PI * (t.y + y / E)) / n))])));
          continue;
        }
        if (!/^(trunk|primary|secondary)$/.test(kind)) continue;
        if (isLabel && !p.ref) continue;
        const ref = isLabel ? String(p.ref) : null;
        for (const line of f.loadGeometry()) {
          let prev = null;
          for (const { x, y } of line) {
            const lon = ((t.x + x / E) / n) * 360 - 180;
            const lat = (180 / Math.PI) * Math.atan(Math.sinh(Math.PI - (2 * Math.PI * (t.y + y / E)) / n));
            const q = toLocal([lon, lat]);
            if (prev) segs.push({ a: prev, b: q, kind, ref });
            prev = q;
          }
        }
      }
    }
  });
  return segs;
}

// grid index over segments; nearest(x, y, ang, maxD, filter) -> segment or null (parallel within 30°)
export function segmentIndex(segs, cell = 50) {
  const grid = new Map();
  segs.forEach((s, i) => {
    const x0 = Math.floor(Math.min(s.a[0], s.b[0]) / cell), x1 = Math.floor(Math.max(s.a[0], s.b[0]) / cell);
    const y0 = Math.floor(Math.min(s.a[1], s.b[1]) / cell), y1 = Math.floor(Math.max(s.a[1], s.b[1]) / cell);
    for (let gx = x0; gx <= x1; gx++) for (let gy = y0; gy <= y1; gy++) { const k = gx * 1e6 + gy; (grid.get(k) ?? grid.set(k, []).get(k)).push(i); }
  });
  const angDiff = (a, b) => { const d = Math.abs(a - b) % Math.PI; return Math.min(d, Math.PI - d); };
  return function nearest(x, y, ang, maxD, filter = () => true) {
    let best = null, bd = maxD;
    const gx = Math.floor(x / cell), gy = Math.floor(y / cell), r = Math.ceil(maxD / cell);
    for (let a = -r; a <= r; a++) for (let b = -r; b <= r; b++) for (const i of grid.get((gx + a) * 1e6 + gy + b) ?? []) {
      const s = segs[i]; if (!filter(s)) continue;
      const dx = s.b[0] - s.a[0], dy = s.b[1] - s.a[1], l2 = dx * dx + dy * dy;
      if (ang != null && l2 > 1 && angDiff(Math.atan2(dy, dx), ang) > Math.PI / 6) continue;
      const u = l2 ? Math.max(0, Math.min(1, ((x - s.a[0]) * dx + (y - s.a[1]) * dy) / l2)) : 0;
      const d = Math.hypot(s.a[0] + u * dx - x, s.a[1] + u * dy - y);
      if (d < bd) { bd = d; best = s; }
    }
    return best;
  };
}

// vote along a polyline (local metres): main vs ordinary prefectural (length), and the national route number
export function voteLink(coords, nearest, maxD = 15) {
  const vote = { main: 0, ord: 0 }, nums = new Map();
  for (let i = 1; i < coords.length; i++) {
    const [ax, ay] = coords[i - 1], [bx, by] = coords[i], L = Math.hypot(bx - ax, by - ay); if (!(L > 0)) continue;
    const ang = Math.atan2(by - ay, bx - ax);
    for (let d = Math.min(10, L / 2); d < L; d += 20) {
      const x = ax + ((bx - ax) * d) / L, y = ay + ((by - ay) * d) / L, w = Math.min(20, L);
      const s = nearest(x, y, ang, maxD, (q) => !q.ref);
      if (s?.kind === 'primary') vote.main += w; else if (s?.kind === 'secondary') vote.ord += w;
      const r = nearest(x, y, ang, maxD, (q) => q.ref && q.kind === 'trunk');
      if (r) for (const m of r.ref.split(/[;,]/)) { const n = parseInt(m, 10); if (n > 0) nums.set(n, (nums.get(n) ?? 0) + w); }
    }
  }
  const routeNo = nums.size ? [...nums].sort((a, b) => b[1] - a[1])[0][0] : 0;
  return { main: vote.main, ord: vote.ord, routeNo };
}
