// Tier 2 traffic for the live builder: betweenness on the MAJOR road network (national + prefectural) of the corridor
// plus a ring around it, from GSI experimental_bvmap z11 tiles (major roads only, ~30 KB per ~20 km tile). A
// corridor-only network would put every through-route on its edge (research-traffic.md §5: rho 0.55 -> 0.48).
// The 'osm' source builds the same network from VersaTiles z11 `streets` (trunk, primary and secondary, the classes
// OSM maps to national and prefectural; roads closed to bikes still carry the cars, so they stay in).
// Same sampled 20-minute betweenness and median normalisation as web/src/traffic.mjs, so the fitted coefficients apply.
import Pbf from '../../vendor/pbf.mjs';
import { VectorTile } from '../../vendor/vector-tile.mjs';
import { betweenness, RADIUS_S, SPEED } from '../traffic.mjs';

const SPEED_RING = { 0: 50, 1: 42 }; // km/h: national; prefectural (z11 has no main/ordinary split)
// per source: the tile layer, and a road's car speed in km/h (0 = not part of the major network)
const RING = {
  gsi: { layer: 'road', kmh: (p) => ((p.rdCtg === 0 || p.rdCtg === 1) && p.motorway !== 1 && Math.floor(p.ftCode / 10) % 10 === 0 ? SPEED_RING[p.rdCtg] : 0) },
  osm: { layer: 'streets', kmh: (p) => (p.kind === 'trunk' ? SPEED[1] : p.kind === 'primary' ? SPEED[2] : p.kind === 'secondary' ? SPEED[4] : 0) },
};

// clip a tile-local polyline to [0,E]^2 (Liang-Barsky per segment, consecutive pieces merged)
function clipLine(pts, E) {
  const out = []; let cur = null;
  for (let i = 1; i < pts.length; i++) {
    let [x0, y0] = pts[i - 1], [x1, y1] = pts[i], t0 = 0, t1 = 1;
    const dx = x1 - x0, dy = y1 - y0; let ok = true;
    for (const [p, q] of [[-dx, x0], [dx, E - x0], [-dy, y0], [dy, E - y0]]) {
      if (p === 0) { if (q < 0) { ok = false; break; } continue; }
      const r = q / p; if (p < 0) { if (r > t1) { ok = false; break; } if (r > t0) t0 = r; } else { if (r < t0) { ok = false; break; } if (r < t1) t1 = r; }
    }
    if (!ok) { cur = null; continue; }
    const a = [x0 + t0 * dx, y0 + t0 * dy], b = [x0 + t1 * dx, y0 + t1 * dy];
    if (cur && cur[cur.length - 1][0] === a[0] && cur[cur.length - 1][1] === a[1]) cur.push(b); else { cur = [a, b]; out.push(cur); }
    if (t1 < 1) cur = null;
  }
  return out;
}

// -> { segs: [{a,b,lbc}] } in local metres; lbc = log10(1+bc) - median over the ring network
export function ringBetweenness(tiles, buffers, toLocal, { k = 1500, source = 'gsi' } = {}) {
  const verts = new Map(), vx = [], vy = [], vkey = (X, Y) => `${Math.round(X)},${Math.round(Y)}`;
  const vid = (X, Y, lon, lat) => { const key = vkey(X, Y); let i = verts.get(key); if (i === undefined) { i = vx.length; verts.set(key, i); const [x, y] = toLocal([lon, lat]); vx.push(x); vy.push(y); } return i; };
  const eu = [], ev = [], et = [], elen = [];
  tiles.forEach((t, kk) => {
    const buf = buffers[kk]; if (!buf || !buf.length) return;
    const L = new VectorTile(new Pbf(buf)).layers[RING[source].layer]; if (!L) return;
    const E = L.extent, n = 2 ** t.z, W = n * E;
    for (let i = 0; i < L.length; i++) {
      const f = L.feature(i); if (f.type !== 2) continue;
      const v = RING[source].kmh(f.properties); if (!v) continue;
      for (const ring of f.loadGeometry()) for (const part of clipLine(ring.map((q) => [q.x, q.y]), E)) {
        let prev = -1;
        for (const [x, y] of part) {
          const GX = t.x * E + x, GY = t.y * E + y;
          const lon = (GX / W) * 360 - 180, lat = (180 / Math.PI) * Math.atan(Math.sinh(Math.PI - (2 * Math.PI * GY) / W));
          const id = vid(GX, GY, lon, lat);
          if (prev >= 0 && prev !== id) { const len = Math.hypot(vx[id] - vx[prev], vy[id] - vy[prev]); eu.push(prev); ev.push(id); elen.push(len); et.push((len / 1000 / v) * 3600); }
          prev = id;
        }
      }
    }
  });
  // snap dangling ends to the nearest other vertex within 30 m (z11 generalisation leaves small gaps at junctions)
  const nV = vx.length, deg = new Int32Array(nV);
  for (let e = 0; e < eu.length; e++) { deg[eu[e]]++; deg[ev[e]]++; }
  const par = Int32Array.from({ length: nV }, (_, i) => i), find = (i) => { while (par[i] !== i) i = par[i] = par[par[i]]; return i; };
  const C = 30, grid = new Map();
  for (let i = 0; i < nV; i++) { const key = Math.floor(vx[i] / C) * 1e6 + Math.floor(vy[i] / C); (grid.get(key) ?? grid.set(key, []).get(key)).push(i); }
  for (let i = 0; i < nV; i++) {
    if (deg[i] !== 1) continue;
    let best = -1, bd = 30; const gx = Math.floor(vx[i] / C), gy = Math.floor(vy[i] / C);
    for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) for (const j of grid.get((gx + a) * 1e6 + gy + b) ?? []) {
      if (j === i) continue; const d = Math.hypot(vx[j] - vx[i], vy[j] - vy[i]); if (d < bd && find(j) !== find(i)) { bd = d; best = j; }
    }
    if (best >= 0) par[find(i)] = find(best);
  }
  const root = new Map(); let nN = 0; const nodeOf = new Int32Array(nV);
  for (let i = 0; i < nV; i++) { const r = find(i); if (!root.has(r)) root.set(r, nN++); nodeOf[i] = root.get(r); }
  const m = eu.length, G = { nNodes: nN, nChains: m, chainA: new Int32Array(m), chainB: new Int32Array(m), atomStart: Int32Array.from({ length: m + 1 }, (_, i) => i), atomLen: Float32Array.from(elen) };
  for (let e = 0; e < m; e++) { G.chainA[e] = nodeOf[eu[e]]; G.chainB[e] = nodeOf[ev[e]]; }
  const tt = Float64Array.from(et);
  const bc = betweenness(G, () => true, { k, radiusS: RADIUS_S, tt });
  // length-weighted median of log10(1+bc) over the ring network
  const vals = []; for (let e = 0; e < m; e++) if (bc[e] > 0) vals.push([Math.log10(1 + bc[e]), elen[e]]);
  vals.sort((a, b) => a[0] - b[0]); const tot = vals.reduce((s, v) => s + v[1], 0); let acc = 0, med = 0;
  for (const [v, L] of vals) { acc += L; if (acc >= tot / 2) { med = v; break; } }
  const segs = [];
  for (let e = 0; e < m; e++) segs.push({ a: [vx[eu[e]], vy[eu[e]]], b: [vx[ev[e]], vy[ev[e]]], lbc: Math.log10(1 + bc[e]) - med });
  return { segs, nodes: nN, edges: m };
}
